        zyg=r[4]; vaf=r[9]; so=r[13]; cls=r[25]
        if zyg=='Reference': continue
        if vaf is None: continue
        try: v=float(vaf)
        except: continue
        if v>=0.3: continue
        if cls is None or str(cls).strip()=='': continue
